 "content": "def transform(grid):
    """Extend the color marks in each column selected by a bottom 5 marker.

    Each selected column is partitioned by the vertical marks already present;
    every cell takes the color of its nearest mark, with ties going downward.
    """
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    for c in range(w):
        if grid[-1][c] != 5:
            continue
        marks = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        for r in range(h):
            # Maximize row on a tie, matching the observed downward boundary.
            _, color = min(marks, key=lambda mark: (abs(mark[0] - r), -mark[0]))
            out[r][c] = color
    return out
